# Shared stack for the RFC 0012 `operator-act@piggy` conformance lanes
# (operator_act_*.bats). Load after common.bash and lib/fibby.bash.
#
# The stack per test:
#
#   fibby (virtual yk5: seeded 9A + 9D, a 9C key generated on the card)
#     <- pcsc -> piggy agent -A            (the card agent, AGENT_SOCK)
#                  <- piggy agent --proxy-only --upstream card=…  (FRONT_SOCK)
#
# The 9C key is generated by `piggy card add-key 9c`, so fibby attests it PIN
# always, touch always: the one policy that serves operator acts. The seeded
# 9A cannot attest at all, which is the fail-closed case.
#
# PIN PROMPT SAFETY NET (piggy-testing(7)): every process here runs under the
# test askpass, which never opens a real prompt. The card agent is given
# PIGGY_TEST_FIB_PIN so it CAN answer a prompt; whether it was asked is read
# from its log, where the askpass leaves one `[piggy-test-askpass]` banner
# per prompt (operator_act_prompt_count).
#
# Required env (supplied by the test-bats-conformance-operator-act recipe):
#   FIBBY_BIN, PIGGY_BIN, OPERATOR_ACT_PROBE_BIN

OPERATOR_ACT_READER="Virtual PCD piggy fibby 00 00"
OPERATOR_ACT_PIN=123456

operator_act_setup() {
  local name
  for name in FIBBY_BIN PIGGY_BIN OPERATOR_ACT_PROBE_BIN; do
    if [[ ! -x ${!name:-/nonexistent} ]]; then
      skip "$name unset or not executable; run via just test-bats-conformance-operator-act"
    fi
  done
  command -v ssh-add >/dev/null || skip "ssh-add not on PATH"
  command -v ssh-keygen >/dev/null || skip "ssh-keygen not on PATH"

  ASKPASS="$PIGGY_BATS_HELPERS_DIR/piggy-test-askpass.sh"
  [[ -x $ASKPASS ]] || skip "piggy-test-askpass.sh not found at $ASKPASS"
  export SSH_ASKPASS="$ASKPASS"
  export SSH_ASKPASS_REQUIRE=force
  export DISPLAY=""
  unset PIGGY_TEST_FIB_PIN PIGGY_TEST_FIB_MGMT_KEY

  # Short-path workdir under /tmp: AF_UNIX sun_path is 108 bytes.
  WORKDIR="$(mktemp -d -t opact.XXXXXX)"
  FIBBY_SOCK="$WORKDIR/pcscd.comm"
  FIBBY_CTL="$WORKDIR/control.sock"
  FIBBY_LOG="$WORKDIR/fibby.log"
  AGENT_SOCK="$WORKDIR/a.sock"
  AGENT_LOG="$WORKDIR/agent.log"
  FRONT_SOCK="$WORKDIR/f.sock"
  FRONT_LOG="$WORKDIR/front.log"
  FIBBY_PID=
  AGENT_PID=
  FRONT_PID=

  # The agent's touch notice goes to a recorder, never to this host's
  # desktop: one `TITLE | MESSAGE` line per notice in $NOTICES.
  NOTICES="$WORKDIR/notices"
  cat >"$WORKDIR/notifier" <<NOTIFIER_EOF
#!/usr/bin/env bash
printf '%s | %s\n' "\$1" "\$2" >>"$NOTICES"
NOTIFIER_EOF
  chmod +x "$WORKDIR/notifier"
  export PIGGY_ASKPASS_NOTIFIER="$WORKDIR/notifier"

  unset SSH_AUTH_SOCK PIGGY_AUTH_SOCK
}

operator_act_teardown() {
  local pid
  for pid in "${FRONT_PID:-}" "${AGENT_PID:-}" "${FIBBY_PID:-}"; do
    [[ -n $pid ]] || continue
    kill "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
  done
  [[ -n ${WORKDIR:-} ]] && rm -rf "$WORKDIR" 2>/dev/null || true
  teardown_test_home 2>/dev/null || true
}

operator_act_dump_logs() {
  local log
  for log in "$AGENT_LOG" "$FRONT_LOG" "$FIBBY_LOG"; do
    [[ -f $log ]] || continue
    echo "--- ${log##*/} (tail) ---" >&2
    tail -40 "$log" >&2 || true
  done
}

operator_act_fail() {
  echo "$1" >&2
  printf 'status: %s\noutput: %s\nstderr: %s\n' "${status:-}" "${output:-}" "${stderr:-}" >&2
  operator_act_dump_logs
  return 1
}

# The card: CHUID, seeded 9A and 9D, and a 9C key generated on the card.
# Extra args go to fibby; with none it runs --auto-touch. A lane that is
# about touch passes its own flags and delivers the touch add-key needs for
# the 9C certificate with operator_act_touch_when_needed.
spawn_operator_card() {
  if [[ $# -eq 0 ]]; then
    set -- --auto-touch
  fi
  spawn_fibby --control-socket "$FIBBY_CTL" --model yk5 \
    --seed-chuid --seed-rfc5903-slot-9d-cert --seed-rfc6979-slot-9a-cert "$@" 3>&-

  local auto_touch=0 arg
  for arg in "$@"; do
    [[ $arg == --auto-touch ]] && auto_touch=1
  done
  PCSCLITE_CSOCK_NAME="$FIBBY_SOCK" \
    PIGGY_TEST_FIB_PIN="$OPERATOR_ACT_PIN" \
    PIGGY_TEST_FIB_MGMT_KEY=default \
    setsid -w "$PIGGY_BIN" card add-key 9c <<<"y" >"$WORKDIR/add-key.out" 2>"$WORKDIR/add-key.err" 3>&- &
  local add_key_pid=$!
  if ((! auto_touch)); then
    operator_act_touch_when_needed 9C 1 || true
  fi
  wait "$add_key_pid" || {
    echo "card add-key 9c failed while preparing the card" >&2
    cat "$WORKDIR/add-key.err" >&2 || true
    return 1
  }
}

# How many touches fibby has asked for on SLOT (`9C`) so far.
operator_act_touches_needed() {
  grep -c "TOUCH needed $1" "$FIBBY_LOG" 2>/dev/null || true
}

# Wait until fibby has asked for its Nth touch on SLOT, then grant it.
operator_act_touch_when_needed() {
  local slot="$1" nth="$2" _
  for _ in $(seq 1 100); do
    if (($(operator_act_touches_needed "$slot") >= nth)); then
      "$FIBBY_BIN" ctl --socket "$FIBBY_CTL" touch "$OPERATOR_ACT_READER" >/dev/null
      return
    fi
    sleep 0.1
  done
  echo "fibby never asked for touch #$nth on $slot" >&2
  return 1
}

_wait_for_socket() {
  local sock="$1" log="$2" _
  for _ in $(seq 1 50); do
    [[ -S $sock ]] && return 0
    sleep 0.1
  done
  echo "agent socket never appeared at $sock" >&2
  cat "$log" >&2 || true
  return 1
}

# The agent next to the card. It may answer PIN prompts (through the test
# askpass) unless OPERATOR_ACT_AGENT_REFUSES_PROMPTS is set, which leaves the
# askpass refusing: the operator cancelling.
spawn_card_agent() {
  local pin="$OPERATOR_ACT_PIN"
  [[ -n ${OPERATOR_ACT_AGENT_REFUSES_PROMPTS:-} ]] && pin=""
  PCSCLITE_CSOCK_NAME="$FIBBY_SOCK" PIGGY_TEST_FIB_PIN="$pin" \
    "$PIGGY_BIN" agent -A -a "$AGENT_SOCK" "$@" >"$AGENT_LOG" 2>&1 3>&- &
  AGENT_PID=$!
  _wait_for_socket "$AGENT_SOCK" "$AGENT_LOG"
}

# A proxy-only front (FDR 0001) over the card agent. It has no card and no
# PIN: PCSCLITE_CSOCK_NAME points nowhere and its askpass refuses, so a
# prompt raised here would fail loudly instead of passing unnoticed.
spawn_proxy_front() {
  PCSCLITE_CSOCK_NAME="$WORKDIR/no-pcscd.comm" \
    "$PIGGY_BIN" agent --proxy-only --upstream "card=$AGENT_SOCK" -a "$FRONT_SOCK" \
    >"$FRONT_LOG" 2>&1 3>&- &
  FRONT_PID=$!
  _wait_for_socket "$FRONT_SOCK" "$FRONT_LOG"
}

operator_act_stack_up() {
  spawn_operator_card "$@"
  spawn_card_agent
}

# How many PIN prompts the agent whose log is $1 has raised.
operator_act_prompt_count() {
  grep -c '^\[piggy-test-askpass\] \(supplying\|REFUSING\)' "$1" 2>/dev/null || true
}

# `piggy operator-sign ARGS` against SOCK ($1) with TEXT ($2) on stdin.
# stdout (the armored sshsig) and stderr are kept apart.
operator_sign_via() {
  local sock="$1" text="$2"
  shift 2
  PIGGY_AUTH_SOCK="$sock" run --separate-stderr "$PIGGY_BIN" operator-sign "$@" <<<"$text"
}

# The raw probe against SOCK ($1); the rest are its flags. Sets the answer's
# lines in $output (`reply …`, `raw …`, `status …`, `detail …`).
operator_act_probe() {
  local sock="$1"
  shift
  run "$OPERATOR_ACT_PROBE_BIN" --socket "$sock" "$@"
  [[ $status -eq 0 ]] || operator_act_fail "the probe could not get an answer"
}

# The numeric RFC 0012 §2.3 status of the last probe answer.
assert_probe_status() {
  local want="$1" name="$2"
  grep -qx "status $want" <<<"$output" ||
    operator_act_fail "expected status $want ($name)"
}

# The key the card agent serves for SLOT (`9C`), as one OpenSSH line.
operator_act_public_key() {
  SSH_AUTH_SOCK="$AGENT_SOCK" ssh-add -L | grep " PIV_slot_$1 " | head -1
}

# Verify the armored sshsig in FILE ($1) over TEXT ($2) under NAMESPACE ($3)
# with the card agent's SLOT ($4) key, the way a verifier would.
assert_sshsig_verifies() {
  local sig_file="$1" text="$2" namespace="$3" slot="$4"
  local key_type key_blob _comment
  read -r key_type key_blob _comment <<<"$(operator_act_public_key "$slot")"
  printf 'operator %s %s\n' "$key_type" "$key_blob" >"$WORKDIR/allowed_signers"
  ssh-keygen -Y verify -f "$WORKDIR/allowed_signers" -I operator \
    -n "$namespace" -s "$sig_file" <<<"$text" >"$WORKDIR/verify.out" 2>&1 || {
    echo "ssh-keygen -Y verify rejected the signature under $namespace:" >&2
    cat "$WORKDIR/verify.out" >&2
    return 1
  }
}
